svg.script:

// 在 SVG XML 规范中，脚本建议包裹在 CDATA 区块内，避免 < 或 & 符号破坏 XML 解析
let clickCount = 0;
const colors = ['#e74c3c', '#2ecc71', '#f1c40f', '#9b59b6', '#e67e22'];

const rect = document.getElementById('clickableRect');
const text = document.getElementById('statusText');

rect.addEventListener('click', function() {
  clickCount++;
  // 随机切换颜色
  const nextColor = colors[clickCount % colors.length];
  rect.style.fill = nextColor;

  // 动态修改 SVG 内部的文本节点
  text.textContent = `脚本正常运行！已点击 ${clickCount} 次`;

  // 测试控制台输出
  console.log(`[SVG Script] 触发点击事件，当前颜色: ${nextColor}`);
});
